#pragma once
#include "layout_composition.hpp"
#include "resource_font.hpp"
struct NativeTextQuad{size_t pane,font,sheet;uint16_t glyph;NativeLayoutQuad quad;};
// Native single-line untagged text adaptation; wrapping and control codes require a text processor.
inline std::vector<NativeTextQuad> layoutTextQuads(const NativeLayoutResource& pose,const std::vector<NativeResourceFont>& fonts){
    auto world=layoutWorldPanes(pose);std::vector<NativeTextQuad> result;
    for(size_t p=0;p<pose.panes.size();++p){const auto& pane=pose.panes[p];if(!pane.text||!world[p].visible)continue;const auto& text=*pane.text;const auto& font=fonts.at(text.font);assetCheck(font.width&&font.height&&text.position<=8,"Invalid native text metrics/alignment");float sx=text.fontSize[0]/font.width,sy=text.fontSize[1]/font.height,lineWidth=0,lineHeight=font.linefeed*sy+text.lineSpace;assetCheck(lineHeight>0&&std::isfinite(lineHeight),"Unsupported text line height");
        for(size_t i=0;i<text.text.size();++i){auto code=text.text[i];assetCheck(code>=32&&!(code>=0xD800&&code<=0xDFFF),"Unsupported native text control/surrogate");if(i)lineWidth+=text.characterSpace;lineWidth+=font.glyphWidths(font.glyphIndex(code)).advance*sx;}assetCheck(std::isfinite(lineWidth)&&lineWidth>=0&&lineWidth<=pane.size[0],"Native text wrapping is not implemented");
        float cursor=-float(pane.base%3)*pane.size[0]*.5f+(pane.size[0]-lineWidth)*float(text.position%3)*.5f,top=float(pane.base/3)*pane.size[1]*.5f-(pane.size[1]-lineHeight)*float(text.position/3)*.5f-(font.ascent-font.baseline)*sy;
        for(size_t i=0;i<text.text.size();++i){if(i)cursor+=text.characterSpace;auto index=font.glyphIndex(text.text[i]);auto widths=font.glyphWidths(index);auto cell=font.glyphCell(index);const auto& sheet=font.sheets.at(cell[0]);assetCheck(cell[1]+widths.width<=sheet.width&&cell[2]+font.cellHeight<=sheet.height,"Native text glyph outside font sheet");if(widths.width){float left=cursor+widths.left*sx,right=left+widths.width*sx,bottom=top-font.cellHeight*sy;NativeLayoutQuad quad{pane.material,{}, {},{text.colors[0],text.colors[0],text.colors[1],text.colors[1]},world[p].alpha};std::array<std::array<float,2>,4> corners{{{left,top},{right,top},{left,bottom},{right,bottom}}};const auto& m=world[p].matrix;for(unsigned j=0;j<4;++j)quad.positions[j]={m[0]*corners[j][0]+m[1]*corners[j][1]+m[2],m[3]*corners[j][0]+m[4]*corners[j][1]+m[5]};for(const auto& corner:quad.positions)for(float coordinate:corner)assetCheck(std::isfinite(coordinate),"Native text coordinate overflow");auto uv=[](uint32_t pixel,uint32_t size){return float(pixel*32768u/size)/32768.f;};float u0=uv(cell[1],sheet.width),u1=uv(cell[1]+widths.width,sheet.width),v0=uv(cell[2],sheet.height),v1=uv(cell[2]+font.cellHeight,sheet.height);quad.uv={u0,v0,u1,v0,u0,v1,u1,v1};result.push_back({p,text.font,cell[0],index,quad});}cursor+=widths.advance*sx;}
    }return result;
}
inline size_t compositeLayoutText(TextureImage& frame,const NativeLayoutResource& pose,const std::vector<NativeResourceFont>& fonts){
    auto glyphs=layoutTextQuads(pose,fonts);size_t painted=0;for(const auto& glyph:glyphs){const auto& source=pose.materials.at(glyph.quad.material);NativeLayoutResource mapping;mapping.origin=pose.origin;mapping.size=pose.size;NativeLayoutMaterial material;material.resourceBits=1;material.textures={{uint16_t(glyph.sheet),0,0}};for(unsigned reg=0;reg<2;++reg)for(unsigned channel=0;channel<4;++channel)material.tevColors[reg][channel]=int16_t(std::clamp(int(source.tevColors[reg][channel]),0,255));mapping.materials.push_back(material);auto quad=glyph.quad;quad.material=0;painted+=compositeLayoutQuads(frame,mapping,{quad},fonts.at(glyph.font).sheets);}return painted;
}
inline void layoutTextGeometryTests(){
    NativeResourceFont font;font.width=10;font.height=20;font.ascent=15;font.baseline=14;font.linefeed=20;font.columns=2;font.rows=1;font.cellWidth=8;font.cellHeight=18;font.sheets={{20,20,2,std::vector<Pixel>(400,{255,255,255,255})}};NativeFontMap map;map.begin=32;map.end=65;map.values={{32,0},{65,1}};font.maps={map};font.widths={{0,{0,0,3}},{1,{-1,8,7}}};NativeLayoutResource layout;NativeLayoutPane pane;pane.flags=1;pane.scale={1,1};pane.size={40,20};pane.base=4;NativeLayoutText text;text.text=u"A A";text.fontSize={10,20};text.position=4;text.characterSpace=1;text.colors={0xFF0000FF,0x0000FFFF};pane.text=text;layout.panes={pane};auto quads=layoutTextQuads(layout,{font});assetCheck(quads.size()==2&&quads[0].quad.positions[0]==std::array<float,2>{-10.5f,9}&&quads[1].quad.positions[0]==std::array<float,2>{1.5f,9}&&quads[0].quad.positions[3]==std::array<float,2>{-2.5f,-9},"Native text advance/space/bearing/baseline alignment mismatch");assetCheck(quads[0].quad.colors[0]==0xFF0000FF&&quads[0].quad.colors[2]==0x0000FFFF,"Native text gradient corner mismatch");layout.panes[0].flags=0;assetCheck(layoutTextQuads(layout,{font}).empty(),"Hidden native text emitted glyphs");
}

